operations.query:
query StratzGetConstants {
	constants {
		heroes {
			id
			name
			localizedName: displayName
			stats {
				primaryAttribute
				attackType
			}
			roles {
				roleId
			}
		}
		items {
			id
			name
			localizedName: displayName
		}
		abilities {
			id
			name
			language {
				displayName
			}
		}
		gameModes {
			id
			name
		}
		regions {
			id
			name
			localizedName: displayName
		}
	}
}

query StratzGetHeroStatsDay ($heroIds: [Short!], $bracketIds: [RankBracket!], $positionIds: [MatchPlayerPositionType!]) {
	heroStats {
		stats: winDay(heroIds: $heroIds, bracketIds: $bracketIds, positionIds: $positionIds, take: 400, skip: 0, groupBy: TIME) {
			heroId
			matchCount
			winCount
			period: day
		}
	}
}

query StratzGetHeroStatsMonth ($heroIds: [Short!], $bracketIds: [RankBracket!], $positionIds: [MatchPlayerPositionType!]) {
	heroStats {
		stats: winMonth(heroIds: $heroIds, bracketIds: $bracketIds, positionIds: $positionIds, take: 18, skip: 0, groupBy: TIME) {
			heroId
			matchCount
			winCount
			period: month
		}
	}
}

query StratzGetHeroStatsWeek ($heroIds: [Short!], $bracketIds: [RankBracket!], $positionIds: [MatchPlayerPositionType!]) {
	heroStats {
		stats: winWeek(heroIds: $heroIds, bracketIds: $bracketIds, positionIds: $positionIds, take: 60, skip: 0, groupBy: TIME) {
			heroId
			matchCount
			winCount
			period: week
		}
	}
}

query StratzGetLeague ($id: Int!) {
	league(id: $id) {
		... LeagueFields
	}
}
fragment LeagueFields on LeagueType {
	id
	name
	displayName
	region
	tier
	startDateTime
	endDateTime
}

query StratzGetMatchBatchFull ($id0: Long!, $id1: Long!, $id2: Long!, $id3: Long!, $id4: Long!) {
	match0: match(id: $id0) {
		... MatchFullFields
	}
	match1: match(id: $id1) {
		... MatchFullFields
	}
	match2: match(id: $id2) {
		... MatchFullFields
	}
	match3: match(id: $id3) {
		... MatchFullFields
	}
	match4: match(id: $id4) {
		... MatchFullFields
	}
}
fragment MatchFullFields on MatchType {
	... MatchStandardFields
	playbackData {
		runeEvents {
			time
			action
			rune
		}
		wardEvents {
			time
			action
			wardType
			fromPlayer
		}
	}
}
fragment MatchStandardFields on MatchType {
	... MatchSummaryFields
	players {
		... MatchPlayerFields
	}
	playbackData {
		buildingEvents {
			time
			type
			isRadiant
			npcId
		}
		roshanEvents {
			time
		}
		towerDeathEvents {
			time
			radiant
			dire
		}
	}
}
fragment MatchSummaryFields on MatchType {
	id
	startDateTime
	durationSeconds
	didRadiantWin
	radiantKills
	direKills
	gameModeId: gameMode
	lobbyTypeId: lobbyType
	regionId
	leagueId
	gameVersionId
	parsedDateTime
	statsDateTime
}
fragment MatchPlayerFields on MatchPlayerType {
	steamAccountId
	heroId
	isRadiant
	playerSlot
	kills
	deaths
	assists
	networth
	level
	imp
}

