query StratzListLiveMatches ($request: MatchLiveRequestType!) {
	live {
		matches(request: $request) {
			id: matchId
			startDateTime: createdDateTime
			gameTime
			gameModeId: gameMode
			spectatorCount: spectators
			radiantTeamId
			direTeamId
			league {
				... LeagueFields
			}
			players {
				steamAccountId
				heroId
				isRadiant
				playerSlot
				kills: numKills
				deaths: numDeaths
				assists: numAssists
				networth
				level
			}
		}
	}
}
fragment LeagueFields on LeagueType {
	id
	name
	displayName
	region
	tier
	startDateTime
	endDateTime
}

